(* IO Configuration*)
config_inputs();
config_outputs();
config_outgroups();

IF IN0300.VAR_OUT.xValueDigital THEN
	//SOFT ShutDown 	
	byPWstate := 1;
ELSIF GVL.blPW_PDU_BCU_READY THEN//PDU READY : CAN2 Mesage Check
	byPWstate := 2;
ELSIF GVL.blPW_MD1_ON AND GVL.blPW_MD1_ON AND GVL.blPW_EHPS_ON THEN//PDU Main power : CAN2 Mesage Check
	byPWstate := 3;
ELSIF GVL.blPW_DCDC1_ON AND GVL.blPW_DCDC2_ON THEN//PDU LV power : CAN2 Mesage Check
	byPWstate := 4;
ELSIF GVL.blPW_TMS01_ON AND GVL.blPW_TMS02_ON AND GVL.blPW_TMS03_ON AND GVL.blPW_TMS04_ON AND GVL.blPW_TMS05_ON THEN//TMS 1~5 power : CAN2A Mesage Check	
	byPWstate := 5;


END_IF;

CASE byPWstate OF
  0 :
  	//Ready
  1 :
    //SOFT ShutDown Set
	OUT0102.VAR_IN.uiValue := 1;
  2 :
  	//CAN_BCU_Relay4_cmd := 1;	//Negative Pole Connection
	//Delay xx ms
	//CAN_BCU_Relay2_cmd := 1;	//Main Precharging Connection
	//Delay xx ms
	//CAN_BCU_Relay1_cmd := 1;	//Main Connection
	//Delay xx ms
	//CAN_BCU_Relay2_cmd := 0;	//Main Precharging NC
	//CAN_BCU_Relay3_cmd := 1;	//Main Connection
  3 : 
  	//CAN_BCU_Relay5_cmd := 1;	//LDC Connection
  4 : 
	//CAN_BCU_Relay7_cmd := 1;	//TMS Precharging Connection	
	//Delay xx ms
	//CAN_BCU_Relay6_cmd := 1;	//TMS Connection
	//Delay xx ms
	//CAN_BCU_Relay7_cmd := 0;	//TMS Precharging NC	

ELSE
  	blIFM_PW_ON := 1;
END_CASE;

IF blPWoff_Delay_Set THEN
	IF (GVL.blPW_MD1_START=0) AND (GVL.blPW_MD2_START=0) AND (GVL.blPW_EHPS_START=0)  THEN
		//IN0106,IN0107,IN0108 Check
		byPWstate := 4;

	END_IF

	CASE byPWstate OF
	  5 : 
		//MD1,2 OFF
		//Motor PWM Stop(Speed 0 Check)
		//Brake On (Motor Lock)
		//Motor Driver1,2 Key On Reset
		//EHPS OFF
		//AIR Cooler HPU off
		//Heater HPU off
		//E-motor HPU Pump Off
	  4 : 
		//TMS Device Cooling Unit 1~5 OFF CMD CAN2A Send  
		//Delay xx ms
		//CAN_BCU_Relay6_cmd := 0;	//TMS Connection
		byPWstate := 3;
	  3 : 
		//CAN_BCU_Relay5_cmd := 0;	//LDC Connection
		byPWstate := 2;
	  2 :
		//CAN_BCU_Relay3_cmd := 0;	//Main Connection
		//Delay xx ms
		//CAN_BCU_Relay1_cmd := 0;	//Main Connection
		//Delay xx ms
		//CAN_BCU_Relay2_cmd := 0;	//Main Precharging Connection
		//Delay xx ms
		//CAN_BCU_Relay4_cmd := 0;	//Negative Pole Connection
		byPWstate := 1;
	  1 :
		//SOFT ShutDown Set
		OUT0102.VAR_IN.uiValue := 0;

	ELSE
			blIFM_PW_Off := TRUE;
	END_CASE;
END_IF

byTimerCnt_1s := byTimerCnt_1s + 1;

IF (byTimerCnt_1s >= 100) THEN			//Monitoring Update Period : 1Sec
//Power Monitoring Value Update
	GVL.blPW_Key := IN0800.VAR_OUT.xValueDigital; 	//IN0800 Power On SW (Key)
	GVL.blPW_MC1 := IN0300.VAR_OUT.xValueDigital;	//IN0300 MC #01 VCU Power Line On
	GVL.blPW_MC2 := IN0301.VAR_OUT.xValueDigital;	//IN0301 MC #02 HPU Pump On
	GVL.blPW_MC3 := IN0400.VAR_OUT.xValueDigital;	//IN0400 MC #03 HPU Air Cooler On
	GVL.blPW_MC4 := IN0401.VAR_OUT.xValueDigital;	//IN0401 MC #04 HPU Heater On
	byTimerCnt_1s := 0;
	//GVL_PC.blPW_LVCG_ON := ;	//LV Charger CAN2 Recieve Flag
	//GVL_PC.blPW_LVBAT_ON := ;	//LV Battery CAN2 Recieve Flag
END_IF

CR721S_Config(); 			//IO Configuration
//ACT_Init_rcan_fbd();
GVL.INIT_COMPLETE := 1;
